def get_divisors(n):
    divs = set()
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

def check_condition(n, divisors):
    if len(divisors) < 5:
        return False, None

    # Divisors are 1, d2, d3, d4, d5, ...
    # a is the 2nd smallest (index 1)
    # b is the 3rd smallest (index 2)
    # c is the 5th smallest (index 4)

    a = divisors[1]
    b = divisors[2]
    c = divisors[4]

    # Check if n = ab + ac + bc
    check_val = a * b + a * c + b * c

    return check_val == n, (a, b, c)

results = []
# Testing n up to 100, starting from the smallest numbers with >= 5 divisors
# We only need to test composite numbers, which is usually handled by the divisor check
for n in range(1, 101):
    divs = get_divisors(n)
    if len(divs) >= 5:
        success, values = check_condition(n, divs)
        if success:
            tau_n = len(divs)
            results.append((n, tau_n, values))

print("--- Results ---")
if results:
    for n, tau, vals in results:
        print(f"n={n}, tau(n)={tau}, Divisors: {get_divisors(n)}, a={vals[0]}, b={vals[1]}, c={vals[2]}. SUCCESS.")
else:
    print("No solutions found up to n=100.")
